def rowdict(row: sqlite3.Row | None) -> dict[str, Any] | None:
    return dict(row) if row is not None else None


def json_rows(rows: list[sqlite3.Row]) -> list[dict[str, Any]]:
    return [dict(row) for row in rows]


def current_user() -> sqlite3.Row | None:
    if not session.get("user_id"):
        return None
    return get_db().execute("SELECT * FROM users WHERE id=? AND active=1", (session["user_id"],)).fetchone()


def is_admin(user: sqlite3.Row | None = None) -> bool:
    user = user or getattr(g, "user", None)
    return bool(user and user["role"] == "Administrator")


def require_roles(*roles: str) -> None:
    user = getattr(g, "user", None)
    if not user:
        raise ApiError("Please sign in again.", 401)
    if user["role"] not in roles:
        raise ApiError("Your role does not have permission to perform this action.", 403)


def ensure_project_access(project_id: int) -> sqlite3.Row:
    db = get_db()
    project = db.execute("SELECT * FROM projects WHERE id=?", (project_id,)).fetchone()
    if not project:
        raise ApiError("Project not found.", 404)
    user = g.user
    member = db.execute("SELECT 1 FROM project_members WHERE project_id=? AND user_id=?", (project_id, user["id"])).fetchone()
    if not member and not is_admin(user):
        raise ApiError("You do not have access to this project.", 403)
    return project


def log_activity(project_id: int, entity_type: str, entity_id: int | None, action: str, details: str = "", user_id: int | None = None) -> None:
    get_db().execute(
        "INSERT INTO activity_logs(user_id,project_id,entity_type,entity_id,action,details,created_at) VALUES(?,?,?,?,?,?,?)",
        (user_id if user_id is not None else g.user["id"], project_id, entity_type, entity_id, action, details[:500], utc_now()),
    )


def payload() -> dict[str, Any]:
    data = request.get_json(silent=True)
    if not isinstance(data, dict):
        raise ApiError("Expected a JSON object.")
    return data


def required_text(value: Any, field: str, max_length: int = 160) -> str:
    if not isinstance(value, str) or not value.strip():
        raise ApiError(f"{field} is required.")
    value = value.strip()
    if len(value) > max_length:
        raise ApiError(f"{field} must be {max_length} characters or fewer.")
    return value


def int_value(value: Any, field: str, default: int = 0, low: int = 0, high: int = 100) -> int:
    if value is None or value == "":
        value = default
    try:
        num = int(value)
    except (TypeError, ValueError):
        raise ApiError(f"{field} must be a whole number.")
    if num < low or num > high:
        raise ApiError(f"{field} must be between {low} and {high}.")
    return num


def task_permissions(task: sqlite3.Row, user: sqlite3.Row, changing_fields: set[str]) -> None:
    if user["role"] in ("Administrator", "Scrum Master", "Product Owner"):
        return
    if user["role"] == "Developer":
        if task["assignee_id"] != user["id"]:
            raise ApiError("Developers can update only their assigned tasks.", 403)
        if not changing_fields.issubset({"status", "blocked_reason"}):
            raise ApiError("Developers can update status and blocker details on their assigned tasks only.", 403)
        return
    raise ApiError("You do not have permission to update this task.", 403)


