    if search:
        query += " AND (LOWER(b.title) LIKE ? OR LOWER(b.description) LIKE ?)"
        args += [f"%{search}%", f"%{search}%"]
    query += " ORDER BY CASE b.priority WHEN 'Must' THEN 0 WHEN 'Should' THEN 1 WHEN 'Could' THEN 2 ELSE 3 END, b.id DESC"
    return jsonify({"items": json_rows(get_db().execute(query, args).fetchall())})


