@app.post("/api/sprints")
def sprint_create_api():
    require_roles("Administrator", "Product Owner", "Scrum Master")
    data = payload()
    project_id = int_value(data.get("project_id"), "Project", default=0, low=1, high=1000000)
    ensure_project_access(project_id)
    name = required_text(data.get("name"), "Sprint name", 120)
    start_date = str(data.get("start_date", ""))
    end_date = str(data.get("end_date", ""))
    try:
        start, end = date.fromisoformat(start_date), date.fromisoformat(end_date)
    except ValueError:
        raise ApiError("Choose valid sprint start and end dates.")
    if end < start: raise ApiError("Sprint end date cannot be before its start date.")
    capacity = int_value(data.get("capacity", 30), "Capacity", default=30, low=1, high=10000)
    status = data.get("status", "Planned")
    if status not in SPRINT_STATUSES: raise ApiError("Invalid sprint status.")
    db = get_db()
    if status == "Active" and db.execute("SELECT 1 FROM sprints WHERE project_id=? AND status='Active'", (project_id,)).fetchone():
        raise ApiError("This project already has an active sprint. Complete it before activating another.")
    cur = db.execute(
        "INSERT INTO sprints(project_id,name,goal,start_date,end_date,capacity,status,created_by,created_at) VALUES(?,?,?,?,?,?,?,?,?)",
        (project_id, name, str(data.get("goal", ""))[:2000], start_date, end_date, capacity, status, g.user["id"], utc_now()),
    )
    log_activity(project_id, "sprint", cur.lastrowid, "created", f"Created sprint: {name}")
    db.commit()
    return jsonify({"ok": True, "id": cur.lastrowid}), 201


@app.patch("/api/sprints/<int:sprint_id>")
def sprint_update_api(sprint_id: int):
    require_roles("Administrator", "Product Owner", "Scrum Master")
    data = payload()
    db = get_db()
    sprint = db.execute("SELECT * FROM sprints WHERE id=?", (sprint_id,)).fetchone()
    if not sprint: raise ApiError("Sprint not found.", 404)
    ensure_project_access(sprint["project_id"])
    fields: dict[str, Any] = {}
    for key in ("name", "goal"):
        if key in data:
            fields[key] = required_text(data[key], "Sprint name", 120) if key == "name" else str(data[key] or "")[:2000]
    if "capacity" in data: fields["capacity"] = int_value(data["capacity"], "Capacity", default=1, low=1, high=10000)
    if "start_date" in data or "end_date" in data:
        start_s = str(data.get("start_date", sprint["start_date"]))
        end_s = str(data.get("end_date", sprint["end_date"]))
        try: start_d, end_d = date.fromisoformat(start_s), date.fromisoformat(end_s)
        except ValueError: raise ApiError("Choose valid sprint dates.")
        if end_d < start_d: raise ApiError("Sprint end date cannot be before its start date.")
        fields.update({"start_date": start_s, "end_date": end_s})
    if "status" in data:
        if data["status"] not in SPRINT_STATUSES: raise ApiError("Invalid sprint status.")
        if data["status"] == "Active" and db.execute("SELECT 1 FROM sprints WHERE project_id=? AND status='Active' AND id<>?", (sprint["project_id"], sprint_id)).fetchone():
            raise ApiError("Another sprint is active. Complete it before activating this sprint.")
        fields["status"] = data["status"]
    if not fields: return jsonify({"ok": True})
    sql = ",".join(f"{key}=?" for key in fields)
    db.execute(f"UPDATE sprints SET {sql} WHERE id=?", [*fields.values(), sprint_id])
    log_activity(sprint["project_id"], "sprint", sprint_id, "updated", f"Updated sprint: {fields.get('name', sprint['name'])}")
    db.commit()
    return jsonify({"ok": True})


