@app.post("/api/tasks")
def task_create_api():
    require_roles("Administrator", "Product Owner", "Scrum Master")
    data = payload()
    project_id = int_value(data.get("project_id"), "Project", default=0, low=1, high=1000000)
    ensure_project_access(project_id)
    title = required_text(data.get("title"), "Task title", 180)
    sprint_id = int_value(data.get("sprint_id"), "Sprint", 0, 0, 1000000) or None
    backlog_id = int_value(data.get("backlog_id"), "Backlog item", 0, 0, 1000000) or None
    assignee_id = int_value(data.get("assignee_id"), "Assignee", 0, 0, 1000000) or None
    if sprint_id and not get_db().execute("SELECT 1 FROM sprints WHERE id=? AND project_id=?", (sprint_id, project_id)).fetchone():
        raise ApiError("Select a sprint belonging to this project.")
    if backlog_id and not get_db().execute("SELECT 1 FROM backlog_items WHERE id=? AND project_id=?", (backlog_id, project_id)).fetchone():
        raise ApiError("Select a backlog item belonging to this project.")
    if assignee_id and not get_db().execute("SELECT 1 FROM project_members WHERE project_id=? AND user_id=?", (project_id, assignee_id)).fetchone():
        raise ApiError("The assignee is not a member of this project.")
    priority = data.get("priority", "Should")
    if priority not in PRIORITIES: raise ApiError("Select a valid priority.")
    points = int_value(data.get("points", 3), "Story points", default=3, low=0, high=100)
    due_date = str(data.get("due_date", ""))
    if due_date:
        try: date.fromisoformat(due_date)
        except ValueError: raise ApiError("Choose a valid due date.")
    now = utc_now()
    cur = get_db().execute(
        "INSERT INTO tasks(project_id,sprint_id,backlog_id,title,description,assignee_id,status,priority,points,due_date,blocked_reason,created_by,created_at,updated_at,completed_at) VALUES(?,?,?,?,?,?, 'To Do',?,?,?,?,?,?,?,'')",
        (project_id, sprint_id, backlog_id, title, str(data.get("description", ""))[:4000], assignee_id, priority, points, due_date, "", g.user["id"], now, now),
    )
    if backlog_id:
        get_db().execute("UPDATE backlog_items SET status='Selected',updated_at=? WHERE id=? AND status<>'Done'", (now, backlog_id))
    log_activity(project_id, "task", cur.lastrowid, "created", f"Created task: {title}")
    get_db().commit()
    return jsonify({"ok": True, "id": cur.lastrowid}), 201


@app.patch("/api/tasks/<int:task_id>")
def task_update_api(task_id: int):
    data = payload()
    db = get_db()
    task = db.execute("SELECT * FROM tasks WHERE id=?", (task_id,)).fetchone()
    if not task: raise ApiError("Task not found.", 404)
    ensure_project_access(task["project_id"])
    changing_fields = set(data.keys())
    task_permissions(task, g.user, changing_fields)
    allowed_fields = {"title", "description", "assignee_id", "status", "priority", "points", "due_date", "blocked_reason", "sprint_id", "backlog_id"}
    if not changing_fields.issubset(allowed_fields): raise ApiError("One or more task fields are not supported.")
    fields: dict[str, Any] = {}
    if "title" in data: fields["title"] = required_text(data["title"], "Task title", 180)
    if "description" in data: fields["description"] = str(data["description"] or "")[:4000]
    if "assignee_id" in data:
        aid = int_value(data["assignee_id"], "Assignee", 0, 0, 1000000) or None
        if aid and not db.execute("SELECT 1 FROM project_members WHERE project_id=? AND user_id=?", (task["project_id"], aid)).fetchone(): raise ApiError("The assignee is not a project member.")
        fields["assignee_id"] = aid
    if "priority" in data:
        if data["priority"] not in PRIORITIES: raise ApiError("Select a valid priority.")
        fields["priority"] = data["priority"]
    if "points" in data: fields["points"] = int_value(data["points"], "Story points", default=0, low=0, high=100)
    if "due_date" in data:
        due = str(data["due_date"] or "")
        if due:
            try: date.fromisoformat(due)
            except ValueError: raise ApiError("Choose a valid due date.")
        fields["due_date"] = due
    if "sprint_id" in data:
        sid = int_value(data["sprint_id"], "Sprint", 0, 0, 1000000) or None
        if sid and not db.execute("SELECT 1 FROM sprints WHERE id=? AND project_id=?", (sid, task["project_id"])).fetchone(): raise ApiError("Select a sprint belonging to this project.")
        fields["sprint_id"] = sid
    if "backlog_id" in data:
        bid = int_value(data["backlog_id"], "Backlog item", 0, 0, 1000000) or None
        if bid and not db.execute("SELECT 1 FROM backlog_items WHERE id=? AND project_id=?", (bid, task["project_id"])).fetchone(): raise ApiError("Select a backlog item belonging to this project.")
        fields["backlog_id"] = bid
    if "status" in data:
        new_status = data["status"]
        if new_status not in TASK_STATUSES: raise ApiError("Select a valid task status.")
        if new_status != task["status"] and new_status not in TRANSITIONS[task["status"]]:
            raise ApiError(f"Invalid workflow transition: {task['status']} → {new_status}.")
        fields["status"] = new_status
        if new_status == "Blocked":
            reason = str(data.get("blocked_reason", task["blocked_reason"] or "")).strip()
            if not reason: raise ApiError("Add a blocker reason before setting this task to Blocked.")
            fields["blocked_reason"] = reason[:1000]
        elif task["status"] == "Blocked" and new_status == "Testing":
            fields["blocked_reason"] = ""
        if new_status == "Done": fields["completed_at"] = utc_now()
        elif task["status"] == "Done" and new_status != "Done": fields["completed_at"] = ""
    if "blocked_reason" in data and "status" not in data:
        fields["blocked_reason"] = str(data["blocked_reason"] or "").strip()[:1000]
    if not fields: return jsonify({"ok": True})
    fields["updated_at"] = utc_now()
    sql = ",".join(f"{key}=?" for key in fields)
    db.execute(f"UPDATE tasks SET {sql} WHERE id=?", [*fields.values(), task_id])
    final_status = fields.get("status", task["status"])
    details = f"Updated task: {fields.get('title', task['title'])}"
    if "status" in fields: details = f"Moved '{task['title']}' from {task['status']} to {final_status}."
    log_activity(task["project_id"], "task", task_id, "updated", details)
    # Keep backlog status in sync with its linked work item.
    backlog_id = fields.get("backlog_id", task["backlog_id"])
    if backlog_id:
        remaining = db.execute("SELECT COUNT(*) FROM tasks WHERE backlog_id=? AND status<>'Done'", (backlog_id,)).fetchone()[0]
        any_tasks = db.execute("SELECT COUNT(*) FROM tasks WHERE backlog_id=?", (backlog_id,)).fetchone()[0]
        backlog_status = "Done" if any_tasks and remaining == 0 else "Selected"
        db.execute("UPDATE backlog_items SET status=?,updated_at=? WHERE id=?", (backlog_status, utc_now(), backlog_id))
    db.commit()
    return jsonify({"ok": True})


