@app.post("/api/users")
def users_create_api():
    require_roles("Administrator")
    data = payload()
    name = required_text(data.get("name"), "Name", 100)
    email = required_text(data.get("email"), "Email", 180).lower()
    if "@" not in email or "." not in email.split("@")[-1]: raise ApiError("Enter a valid email address.")
    password = required_text(data.get("password"), "Temporary password", 120)
    if len(password) < 8: raise ApiError("Temporary password must be at least 8 characters.")
    role = data.get("role")
    if role not in ROLES: raise ApiError("Select a valid role.")
    db = get_db()
    try:
        cur = db.execute("INSERT INTO users(name,email,password_hash,role,active,created_at) VALUES(?,?,?,?,1,?)", (name, email, generate_password_hash(password), role, utc_now()))
    except sqlite3.IntegrityError:
        raise ApiError("An account with this email already exists.")
    user_id = cur.lastrowid
    for project in db.execute("SELECT id FROM projects").fetchall():
        db.execute("INSERT OR IGNORE INTO project_members(project_id,user_id) VALUES(?,?)", (project["id"], user_id))
    for project in db.execute("SELECT id FROM projects").fetchall():
        log_activity(project["id"], "user", user_id, "created", f"Added team member: {name} ({role})")
    db.commit()
    return jsonify({"ok": True, "id": user_id}), 201


@app.patch("/api/users/<int:user_id>")
def users_update_api(user_id: int):
    require_roles("Administrator")
    if user_id == g.user["id"] and payload().get("active") in (0, False):
        raise ApiError("You cannot deactivate your own active session.")
    data = request.get_json(silent=True) or {}
    db = get_db()
    user = db.execute("SELECT * FROM users WHERE id=?", (user_id,)).fetchone()
    if not user: raise ApiError("User not found.", 404)
    fields = {}
    if "role" in data:
        if data["role"] not in ROLES: raise ApiError("Select a valid role.")
        fields["role"] = data["role"]
    if "active" in data:
        fields["active"] = 1 if data["active"] else 0
    if "name" in data: fields["name"] = required_text(data["name"], "Name", 100)
    if not fields: return jsonify({"ok": True})
    sql = ",".join(f"{key}=?" for key in fields)
    db.execute(f"UPDATE users SET {sql} WHERE id=?", [*fields.values(), user_id])
    for project in db.execute("SELECT project_id FROM project_members WHERE user_id=?", (user_id,)).fetchall():
        log_activity(project["project_id"], "user", user_id, "updated", f"Updated team member {user['name']}.")
    db.commit()
    return jsonify({"ok": True})


@app.post("/api/projects")
def projects_create_api():
    require_roles("Administrator")
    data = payload()
    name = required_text(data.get("name"), "Project name", 120)
    description = str(data.get("description", ""))[:2000]
    base_key = "".join(ch for ch in name.upper() if ch.isalnum())[:6] or "PROJ"
    key, suffix = base_key, 1
    db = get_db()
    while db.execute("SELECT 1 FROM projects WHERE project_key=?", (key,)).fetchone():
        suffix += 1
        key = f"{base_key[:5]}{suffix}"
    cur = db.execute("INSERT INTO projects(name,project_key,description,created_by,created_at) VALUES(?,?,?,?,?)", (name, key, description, g.user["id"], utc_now()))
    pid = cur.lastrowid
    active_users = db.execute("SELECT id FROM users WHERE active=1").fetchall()
    db.executemany("INSERT OR IGNORE INTO project_members(project_id,user_id) VALUES(?,?)", [(pid, row["id"]) for row in active_users])
    log_activity(pid, "project", pid, "created", f"Created project: {name}")
    db.commit()
    return jsonify({"ok": True, "id": pid}), 201


@app.get("/api/export/<kind>")
def export_csv_api(kind: str):
    project_id = int(request.args.get("project_id", "0") or 0)
    ensure_project_access(project_id)
    db = get_db()
    if kind == "tasks":
        rows = db.execute("SELECT t.id,p.name AS project,s.name AS sprint,t.title,t.description,u.name AS assignee,t.status,t.priority,t.points,t.due_date,t.blocked_reason,t.created_at,t.updated_at,t.completed_at FROM tasks t JOIN projects p ON p.id=t.project_id LEFT JOIN sprints s ON s.id=t.sprint_id LEFT JOIN users u ON u.id=t.assignee_id WHERE t.project_id=? ORDER BY t.id", (project_id,)).fetchall()
        filename = "asms_tasks.csv"
    elif kind == "backlog":
        rows = db.execute("SELECT id,title,description,acceptance_criteria,priority,points,status,created_at,updated_at FROM backlog_items WHERE project_id=? ORDER BY id", (project_id,)).fetchall()
        filename = "asms_backlog.csv"
    elif kind == "sprints":
        rows = db.execute("SELECT s.id,s.name,s.goal,s.start_date,s.end_date,s.capacity,s.status,COUNT(t.id) AS task_count,SUM(CASE WHEN t.status='Done' THEN 1 ELSE 0 END) AS completed_tasks,COALESCE(SUM(t.points),0) AS total_points,COALESCE(SUM(CASE WHEN t.status='Done' THEN t.points ELSE 0 END),0) AS velocity FROM sprints s LEFT JOIN tasks t ON t.sprint_id=s.id WHERE s.project_id=? GROUP BY s.id ORDER BY s.id", (project_id,)).fetchall()
        filename = "asms_sprints.csv"
    elif kind == "activity":
        rows = db.execute("SELECT a.id,u.name AS user,a.entity_type,a.entity_id,a.action,a.details,a.created_at FROM activity_logs a LEFT JOIN users u ON u.id=a.user_id WHERE a.project_id=? ORDER BY a.id DESC", (project_id,)).fetchall()
        filename = "asms_activity.csv"
    else:
        raise ApiError("Unknown export type.", 404)
    output = io.StringIO(newline="")
    if rows:
        writer = csv.DictWriter(output, fieldnames=list(rows[0].keys()))
        writer.writeheader()
        for row in rows:
            # Prefix potentially dangerous spreadsheet formula starters in exported cells.
            values = dict(row)
            for key, value in values.items():
                if isinstance(value, str) and value.startswith(("=", "+", "-", "@")):
                    values[key] = "'" + value
            writer.writerow(values)
    response = make_response(output.getvalue())
    response.headers["Content-Type"] = "text/csv; charset=utf-8"
    response.headers["Content-Disposition"] = f'attachment; filename="{filename}"'
    return response


